insert into public.kids_seasons(level_id,code,season_no,name,learning_stage,base_goal,depth_goal,mission_count,page_count,transition_rule,sort_order,is_active)
select l.id,s.code,s.season_no,s.name,s.learning_stage,s.base_goal,s.depth_goal,s.mission_count,s.page_count,s.transition_rule,s.sort_order,true
from src s join public.kids_levels l on l.code=s.level_code
on conflict (code) do update set
 level_id=excluded.level_id, season_no=excluded.season_no, name=excluded.name, learning_stage=excluded.learning_stage,
 base_goal=excluded.base_goal, depth_goal=excluded.depth_goal, mission_count=excluded.mission_count,
 page_count=excluded.page_count, transition_rule=excluded.transition_rule, sort_order=excluded.sort_order, is_active=true, updated_at=now();
